#!/usr/bin/env node
// Generates the static language versions of the home page from index.html +
// assets/js/languages/translations.js, so search engines get real text in
// each language instead of text swapped in by JavaScript.
//
//   node scripts/build-i18n.mjs
//
// - index.html     → rewritten in place with the English texts (idempotent)
// - es/index.html  → generated Spanish version (do not edit by hand)
// - projects/<slug>/index.html and es/proyectos/<slug>/index.html → project
//   case-study pages from scripts/data/projects.mjs (do not edit by hand)
// - sitemap.xml    → the block between <!-- projects:start/end --> is rewritten
// - llms.txt, llms-full.txt → profile for AI search engines and agents
//   (scripts/data/profile.mjs + projects.mjs + scripts/cv/data.mjs)
//
// Markup conventions (see switchLanguages.js, which uses the same ones at runtime):
//   data-i18n="key.path"            element text is replaced by the translation
//   data-i18n-attr="attr:key;..."   attribute values are replaced by translations
// Elements with data-i18n must contain only text (no nested tags of the same name).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const { default: translations } = await import(
  path.join(root, 'assets/js/languages/translations.js')
);
const { translate } = await import(path.join(root, 'assets/js/languages/translate.js'));

const escapeText = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escapeAttr = (s) => escapeText(s).replace(/"/g, '&quot;');

const missing = new Set();
const t = (key, lang) => {
  const value = translate(translations, key, lang);
  if (typeof value !== 'string') {
    missing.add(`${key} (${lang})`);
    return null;
  }
  return value;
};

function render(html, lang) {
  // <html lang="..">
  let out = html.replace(/<html lang="[^"]*"/, `<html lang="${lang}"`);

  // Element text: <tag ... data-i18n="key" ...>text</tag>
  out = out.replace(
    /(<([a-zA-Z][a-zA-Z0-9]*)\b[^>]*?\sdata-i18n="([^"]+)"[^>]*>)([\s\S]*?)(<\/\2>)/g,
    (m, open, _tag, key, _text, close) => {
      const value = t(key, lang);
      return value === null ? m : `${open}${escapeText(value)}${close}`;
    },
  );

  // Attributes: <tag ... data-i18n-attr="content:meta.title;href:meta.url" ...>
  out = out.replace(/<[a-zA-Z][^>]*?\sdata-i18n-attr="([^"]+)"[^>]*>/g, (tag, spec) => {
    for (const pair of spec.split(';')) {
      const [attr, key] = pair.split(':').map((s) => s.trim());
      const value = t(key, lang);
      if (value === null) continue;
      const attrRe = new RegExp(`(\\s${attr}=")[^"]*(")`);
      tag = tag.replace(attrRe, `$1${escapeAttr(value)}$2`);
    }
    return tag;
  });

  // Structured data: <script type="application/ld+json" data-i18n-jsonld>
  // gets translations.meta[lang].jsonLd merged over its fields.
  out = out.replace(
    /(<script type="application\/ld\+json" data-i18n-jsonld>)([\s\S]*?)(\n(\s*)<\/script>)/,
    (m, open, body, close, indent) => {
      const overrides = translations.meta?.[lang]?.jsonLd;
      if (!overrides) return m;
      const data = { ...JSON.parse(body), ...overrides };
      const json = JSON.stringify(data, null, 2)
        .replace(/</g, '\\u003c') // never close the <script> early
        .split('\n')
        .map((line) => `${indent}  ${line}`)
        .join('\n');
      return `${open}\n${json}${close}`;
    },
  );

  return out;
}

const sourcePath = path.join(root, 'index.html');
const source = fs.readFileSync(sourcePath, 'utf8');

const en = render(source, 'en');
const es = render(source, 'es');

if (missing.size) {
  console.error('Missing translations:\n  ' + [...missing].join('\n  '));
  process.exit(1);
}

fs.writeFileSync(sourcePath, en);
fs.mkdirSync(path.join(root, 'es'), { recursive: true });
fs.writeFileSync(
  path.join(root, 'es/index.html'),
  es.replace(
    '<!DOCTYPE html>',
    '<!DOCTYPE html>\n<!-- GENERATED by scripts/build-i18n.mjs from index.html — do not edit -->',
  ),
);

console.log('✔ index.html (en) and es/index.html (es) generated');

// ---------------------------------------------------------------------------
// Project case-study pages
// ---------------------------------------------------------------------------
const { default: projects } = await import(path.join(root, 'scripts/data/projects.mjs'));
const { projectPage, projectPath, adaptHeader, SITE } = await import(
  path.join(root, 'scripts/lib/project-page.mjs')
);

const header = en.match(/ {4}<header class="header">[\s\S]*?<\/header>/)?.[0];
const footer = en.match(/ {4}<footer class="footer section">[\s\S]*?<\/footer>/)?.[0];
if (!header || !footer) {
  console.error('Could not find the header/footer in index.html');
  process.exit(1);
}

const banner = '<!-- GENERATED by scripts/build-i18n.mjs from scripts/data/projects.mjs — do not edit -->';
for (const dir of ['projects', 'es/proyectos']) {
  fs.rmSync(path.join(root, dir), { recursive: true, force: true }); // drop renamed/removed slugs
}

projects.forEach((project, i) => {
  const prev = projects[(i - 1 + projects.length) % projects.length];
  const next = projects[(i + 1) % projects.length];
  for (const lang of ['en', 'es']) {
    const page = projectPage({ project, lang, prev, next, header: adaptHeader(header, lang), footer });
    const html = render(page, lang).replace('<!DOCTYPE html>', `<!DOCTYPE html>\n${banner}`);
    const file = path.join(root, projectPath(project, lang), 'index.html');
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, html);
  }
});

if (missing.size) {
  console.error('Missing translations:\n  ' + [...missing].join('\n  '));
  process.exit(1);
}

// Sitemap entries for the project pages (with hreflang alternates)
const sitemapPath = path.join(root, 'sitemap.xml');
const sitemap = fs.readFileSync(sitemapPath, 'utf8');
const today = new Date().toISOString().slice(0, 10);
const entries = projects
  .flatMap((project) => {
    const alt = ['en', 'es']
      .map((l) => `        <xhtml:link rel="alternate" hreflang="${l}" href="${SITE}${projectPath(project, l)}" />`)
      .concat(`        <xhtml:link rel="alternate" hreflang="x-default" href="${SITE}${projectPath(project, 'en')}" />`)
      .join('\n');
    return ['en', 'es'].map(
      (lang) => `    <url>
        <loc>${SITE}${projectPath(project, lang)}</loc>
${alt}
        <lastmod>${today}</lastmod>
        <changefreq>yearly</changefreq>
        <priority>0.7</priority>
    </url>`,
    );
  })
  .join('\n');
const block = `    <!-- projects:start (generated by scripts/build-i18n.mjs) -->\n${entries}\n    <!-- projects:end -->`;
const markerRe = / {4}<!-- projects:start[\s\S]*?<!-- projects:end -->/;
fs.writeFileSync(
  sitemapPath,
  markerRe.test(sitemap) ? sitemap.replace(markerRe, block) : sitemap.replace('</urlset>', `${block}\n</urlset>`),
);

console.log(`✔ ${projects.length * 2} project pages and sitemap.xml generated`);

// ---------------------------------------------------------------------------
// llms.txt / llms-full.txt (AI search engines and agents)
// ---------------------------------------------------------------------------
const { default: profile } = await import(path.join(root, 'scripts/data/profile.mjs'));
const { default: cv } = await import(path.join(root, 'scripts/cv/data.mjs'));
const { llmsTxt, llmsFullTxt } = await import(path.join(root, 'scripts/lib/llms.mjs'));
const llmsData = { site: SITE, profile, projects, cv };
fs.writeFileSync(path.join(root, 'llms.txt'), llmsTxt(llmsData));
fs.writeFileSync(path.join(root, 'llms-full.txt'), llmsFullTxt(llmsData));
console.log('✔ llms.txt and llms-full.txt generated');
